	{
		NAMES[value] = name;
		PATCHES[value] = patch;
	}

	public final int value;
	public final String name;
	public final String patchKind;
	/** The crop if it's one this plugin plants (herb, tree, fruit tree), otherwise null. */
	public final Crop crop;
	public final boolean complete;

	private FarmingContract(int value, boolean complete)
	{
		this.value = value;
		this.name = NAMES[value];
		this.patchKind = PATCHES[value];
		this.complete = complete;
		Crop match = null;
		for (Crop c : Crop.values())
		{
			if (c.getDisplayName().equalsIgnoreCase(name) && kind(c.getType()).equals(patchKind))
			{
				match = c;
			}
		}
		this.crop = match;
	}

	private static String kind(PatchType t)
	{
		return t == PatchType.HERB ? "herb" : t == PatchType.TREE ? "tree" : t == PatchType.FRUIT_TREE ? "fruit tree" : "hardwood";
	}

	/** Null when there's no contract (or the value is unknown). */
	public static FarmingContract of(int typeValue, int completeValue)
	{
		if (typeValue <= 0 || typeValue >= NAMES.length || NAMES[typeValue] == null)
		{
			return null;
		}
		return new FarmingContract(typeValue, completeValue > 0);
	}

	/** The Farming Guild patch the contract crop goes in, if it's one of the run's patch types. */
	public FarmPatch guildPatch()
	{
		if (crop == null)
		{
			return null;
		}
		switch (crop.getType())
		{
			case HERB:
				return FarmPatch.FARMING_GUILD_HERB;
			case TREE:
				return FarmPatch.FARMING_GUILD_TREE;
			case FRUIT_TREE:
				return FarmPatch.FARMING_GUILD_FRUIT;
			default:
				return null;
		}
	}

	public String describe()
	{
		if (complete)
		{
			return "Contract done: talk to Guildmaster Jane for your seed pack and a new contract.";
		}
		String where = "in the Farming Guild " + patchKind + " patch";
		return "Grow " + name.toLowerCase() + " " + where + ".";
	}
}

package com.herbrunhelper;

import java.util.EnumMap;
import java.util.Map;

/**
 * When crops will be ready. Crops grow on fixed clock ticks (20 min herbs, 40 min trees,
 * 160 min fruit trees, 640 min hardwood) shifted by a per-account offset. The offset is learned
 * by watching a patch change stage while you stand near it (the approach RuneLite's Time
 * Tracking uses). Pure Java so it can be tested.
 */
public final class GrowthClock
{
	private final Map<PatchType, Long> phaseMillis = new EnumMap<>(PatchType.class);

	public synchronized void learn(PatchType type, long changedAt)
	{
		long tick = tickMillis(type);
		phaseMillis.put(type, Math.floorMod(changedAt, tick));
	}

	public synchronized boolean knows(PatchType type)
	{
		return phaseMillis.containsKey(type);
	}

	public synchronized String serialize()
	{
		StringBuilder sb = new StringBuilder();
		phaseMillis.forEach((t, p) -> sb.append(sb.length() > 0 ? ";" : "").append(t.name()).append(':').append(p));
		return sb.toString();
	}

	public synchronized void load(String data)
	{
		phaseMillis.clear();
		if (data == null || data.isEmpty())
		{
			return;
		}
		for (String part : data.split(";"))
		{
			String[] kv = part.split(":");
			try
			{
				phaseMillis.put(PatchType.valueOf(kv[0]), Long.parseLong(kv[1]));
			}
			catch (RuntimeException ignored)
			{
				// old or bad entry
			}
		}
	}

	public static long tickMillis(PatchType type)
	{
		return type.getTickMinutes() * 60_000L;
	}

	/** The next growth tick after now. */
	public synchronized long nextTick(PatchType type, long now)
	{
		long tick = tickMillis(type);
		long phase = phaseMillis.getOrDefault(type, 0L);
		return Math.floorDiv(now - phase, tick) * tick + phase + tick;
	}

	/** Ready time for a crop seen at this growth stage right now. */
	public long readyFromLive(Crop crop, int stage, long now)
	{
		int last = crop.getStages() - 1;
		if (stage >= last)
		{
			return now;
		}
		return nextTick(crop.getType(), now) + (long) (last - 1 - stage) * tickMillis(crop.getType());
	}

	/** Ready time for a crop that reached this stage at changedAt. */
	public static long readyFromChange(Crop crop, int stage, long changedAt)
	{
		int last = crop.getStages() - 1;
		return changedAt + (long) Math.max(0, last - stage) * tickMillis(crop.getType());
	}
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Item ids for working out herb profit (game item ids, as in RuneLite's ItemID), and the
 * profit-per-patch sums. Pure Java: prices are passed in.
 */
public final class HerbPrices
{
	/** Rough average herbs per patch with compost, used until your own runs give a better number. */
	public static final double DEFAULT_YIELD = 8.0;

	private static final Map<Crop, int[]> IDS = new EnumMap<>(Crop.class);

	static
	{
		// {grimy herb, seed}
		IDS.put(Crop.GUAM, new int[]{199, 5291});
		IDS.put(Crop.MARRENTILL, new int[]{201, 5292});
		IDS.put(Crop.TARROMIN, new int[]{203, 5293});
		IDS.put(Crop.HARRALANDER, new int[]{205, 5294});
		IDS.put(Crop.RANARR, new int[]{207, 5295});
		IDS.put(Crop.TOADFLAX, new int[]{3049, 5296});
		IDS.put(Crop.IRIT, new int[]{209, 5297});
		IDS.put(Crop.AVANTOE, new int[]{211, 5298});
		IDS.put(Crop.KWUARM, new int[]{213, 5299});
		IDS.put(Crop.HUASCA, new int[]{30094, 30088});
		IDS.put(Crop.SNAPDRAGON, new int[]{3051, 5300});
		IDS.put(Crop.CADANTINE, new int[]{215, 5301});
		IDS.put(Crop.LANTADYME, new int[]{2485, 5302});
		IDS.put(Crop.DWARF_WEED, new int[]{217, 5303});
		IDS.put(Crop.TORSTOL, new int[]{219, 5304});
	}

	private HerbPrices()
	{
	}

	public static int grimyId(Crop crop)
	{
		int[] ids = IDS.get(crop);
		return ids == null ? -1 : ids[0];
	}

	public static int seedId(Crop crop)
	{
		int[] ids = IDS.get(crop);
		return ids == null ? -1 : ids[1];
	}

	/** The item you get when harvesting: grimy herbs, fruit, or logs. */
	public static int produceId(Crop crop)
	{
		int grimy = grimyId(crop);
		return grimy > 0 ? grimy : crop.getIconItemId();
	}

	/** Profit for one patch: yield x herb price - seed price. */
	public static int profitPerPatch(double yield, long herbPrice, long seedPrice)
	{
		return (int) Math.round(yield * herbPrice - seedPrice);
	}

	/** Herbs ordered most profitable first (only crops with a known price). */
	public static List<Crop> rankByProfit(Map<Crop, Integer> profit)
	{
		List<Crop> out = new ArrayList<>(profit.keySet());
		out.sort((a, b) -> Integer.compare(profit.get(b), profit.get(a)));
		return out;
	}

	/** 1234 -> "1.2k", 2500000 -> "2.5m". */
	public static String gp(long value)
	{
		long abs = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		if (abs >= 1_000_000)
		{
			return sign + String.format("%.1fm", abs / 1_000_000.0);
		}
		if (abs >= 10_000)
		{
			return sign + (abs / 1000) + "k";
		}
		if (abs >= 1000)
		{
			return sign + String.format("%.1fk", abs / 1000.0);
		}
		return sign + abs;
	}
}

package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Outlines the items you still need to withdraw while the bank is open. */
public class HerbRunBankOverlay extends WidgetItemOverlay
{
	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;

	@Inject
	HerbRunBankOverlay(HerbRunPlugin plugin, HerbRunConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.highlightBank() || !plugin.getHighlightIds().contains(itemId))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		Color c = config.highlightColor();
		graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 60));
		graphics.fill(bounds);
		graphics.setColor(c);
		graphics.setStroke(new BasicStroke(2));
		graphics.draw(bounds);
	}
}

